using Azure.Storage.Blobs;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDay.Api.Data;using RaceDay.Api.Models;using System.Security.Claims;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api")]
public class MediaController(IConfiguration config,RaceDayDbContext db):ControllerBase{
 [Authorize(Roles=Roles.Organiser),HttpPost("events/{eventId:int}/banner")]
 public async Task<IActionResult> EventBanner(int eventId,IFormFile file){var userId=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var ev=await db.Events.FindAsync(eventId);if(ev==null)return NotFound();if(ev.OrganiserId!=userId)return Forbid();var result=await Save(file,$"events/{eventId}");if(result is OkObjectResult ok&&ok.Value is MediaResponse media){ev.BannerUrl=media.Url;await db.SaveChangesAsync();}return result;}
 [Authorize(Roles=Roles.Participant),HttpPost("profile/image")]
 public async Task<IActionResult> ProfileImage(IFormFile file){var id=int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);var user=await db.Users.FindAsync(id);if(user==null)return NotFound();var result=await Save(file,$"profiles/{id}");if(result is OkObjectResult ok&&ok.Value is MediaResponse media){user.ProfileImageUrl=media.Url;await db.SaveChangesAsync();}return result;}
 async Task<IActionResult> Save(IFormFile file,string folder){var cs=config["AzureBlobStorage:ConnectionString"];if(string.IsNullOrWhiteSpace(cs))return StatusCode(503,new{message="Azure Blob Storage is not configured. Set AzureBlobStorage__ConnectionString."});if(file==null||file.Length==0)return BadRequest(new{message="Choose an image file."});if(file.Length>5*1024*1024)return BadRequest(new{message="Images must be 5 MB or smaller."});if(!file.ContentType.StartsWith("image/"))return BadRequest(new{message="Only image files are accepted."});var service=new BlobServiceClient(cs);var container=service.GetBlobContainerClient("raceday-media");await container.CreateIfNotExistsAsync(Azure.Storage.Blobs.Models.PublicAccessType.Blob);var name=$"{folder}/{Guid.NewGuid():N}{Path.GetExtension(file.FileName)}";var blob=container.GetBlobClient(name);await using var stream=file.OpenReadStream();await blob.UploadAsync(stream,true);return Ok(new MediaResponse(blob.Uri.ToString(),name,"Image uploaded to Azure Blob Storage."));}
 public record MediaResponse(string Url,string FileName,string Message);
}